 if(t.job==='plant'){b+='<path d="M262 166H338L328 225H272Z" fill="#c78e6e" stroke="#90654c" stroke-width="3"/><ellipse cx="300" cy="166" rx="38" ry="8" fill="#7a6653"/><path d="M300 165V110M300 141Q267 108 272 137Q283 153 300 150M300 127Q331 91 329 119Q314 139 300 137" fill="#8ea96d" stroke="#648057" stroke-width="4"/>';if(done)b+='<circle cx="300" cy="102" r="17" fill="#d9b864"/><circle cx="300" cy="102" r="7" fill="#bd7a55"/><path d="M360 100Q375 87 395 100V146H355V109L333 124L327 115Z" fill="#8eb1bc" stroke="#537982" stroke-width="3"/><path d="M394 107Q421 92 415 124Q408 138 395 129" fill="none" stroke="#537982" stroke-width="7"/><path d="M328 122L304 162M335 126L311 163" stroke="#8db9cf" stroke-width="3" stroke-dasharray="5 5"/>';}
